<?php
$page_title="Periode & harga voting";include "_header.php";
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$nama=trim($_POST['nama_periode']);$mulai=$_POST['tanggal_mulai'];$selesai=$_POST['tanggal_selesai'];$status=$_POST['status'];$harga=(int)$_POST['harga_per_suara'];$rekening=trim($_POST['rekening']??'');$pemilik=trim($_POST['pemilik_rekening']??'');if($status==='Aktif')$conn->query("UPDATE periode_voting SET status='Nonaktif'");if($id){$s=$conn->prepare("UPDATE periode_voting SET nama_periode=?,tanggal_mulai=?,tanggal_selesai=?,status=?,harga_per_suara=?,rekening=?,pemilik_rekening=? WHERE id=?");$s->bind_param("ssssiisi",$nama,$mulai,$selesai,$status,$harga,$rekening,$pemilik,$id);}else{$s=$conn->prepare("INSERT INTO periode_voting(nama_periode,tanggal_mulai,tanggal_selesai,status,harga_per_suara,rekening,pemilik_rekening) VALUES(?,?,?,?,?,?,?)");$s->bind_param("ssssiss",$nama,$mulai,$selesai,$status,$harga,$rekening,$pemilik);}if($s->execute())flash("Pengaturan periode disimpan.");else flash("Gagal menyimpan periode.","danger");redirect("periode.php");}
$edit=null;if(isset($_GET['edit'])){$id=(int)$_GET['edit'];$s=$conn->prepare("SELECT * FROM periode_voting WHERE id=?");$s->bind_param("i",$id);$s->execute();$edit=$s->get_result()->fetch_assoc();}
?>
<div class="panel p-3 p-md-4 mb-4"><h5 class="admin-title"><?= $edit?'Edit':'Buat' ?> periode</h5><form method="post" class="row g-3"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><div class="col-md-6"><label class="form-label">Nama periode</label><input class="form-control" name="nama_periode" required value="<?=e($edit['nama_periode']??'Pemilihan Kakang Senduk Ponorogo 2026')?>"></div><div class="col-md-3"><label class="form-label">Mulai</label><input class="form-control" type="datetime-local" name="tanggal_mulai" required value="<?=isset($edit['tanggal_mulai'])?date('Y-m-d\TH:i',strtotime($edit['tanggal_mulai'])):''?>"></div><div class="col-md-3"><label class="form-label">Selesai</label><input class="form-control" type="datetime-local" name="tanggal_selesai" required value="<?=isset($edit['tanggal_selesai'])?date('Y-m-d\TH:i',strtotime($edit['tanggal_selesai'])):''?>"></div><div class="col-md-3"><label class="form-label">Harga per suara (Rp)</label><input class="form-control" type="number" min="0" name="harga_per_suara" required value="<?=e($edit['harga_per_suara']??1000)?>"></div><div class="col-md-3"><label class="form-label">Status</label><select class="form-select" name="status"><option <?=($edit['status']??'Aktif')==='Aktif'?'selected':''?>>Aktif</option><option <?=($edit['status']??'')==='Nonaktif'?'selected':''?>>Nonaktif</option></select></div><div class="col-md-3"><label class="form-label">Nomor rekening</label><input class="form-control" name="rekening" value="<?=e($edit['rekening']??'')?>"></div><div class="col-md-3"><label class="form-label">Atas nama</label><input class="form-control" name="pemilik_rekening" value="<?=e($edit['pemilik_rekening']??'')?>"></div><div class="col-12"><button class="btn btn-maroon">Simpan periode</button></div></form></div>
<div class="panel p-3 p-md-4"><h5 class="admin-title">Daftar periode</h5><div class="table-responsive"><table class="table"><thead><tr><th>Periode</th><th>Jadwal</th><th>Harga/suara</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php $q=$conn->query("SELECT * FROM periode_voting ORDER BY id DESC");while($r=$q->fetch_assoc()):?><tr><td><?=e($r['nama_periode'])?></td><td><?=e($r['tanggal_mulai'])?><br><?=e($r['tanggal_selesai'])?></td><td>Rp <?=number_format($r['harga_per_suara'],0,',','.')?></td><td><?=e($r['status'])?></td><td><a href="?edit=<?=$r['id']?>">Edit</a></td></tr><?php endwhile;?></tbody></table></div></div>
<?php include "_footer.php"; ?>